"""Writes src/shared/ItemModelData.luau from art/export/manifest.json:
python art/blender/manifest_to_luau.py
"""
import json
import os

root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
man = json.load(open(os.path.join(root, "art", "export", "manifest.json")))


def v3(a):
    return f"Vector3.new({a[0]}, {a[1]}, {a[2]})"


lines = [
    "--!strict",
    "-- Generated by art/blender/manifest_to_luau.py from art/export/manifest.json (task R5). Do not edit.",
    "-- Per mesh: size (studs, as exported), center (where the mesh centre sits from the item's origin: floor",
    "-- centre of gym pieces / crates / treats / shoes, the hand grip of rods / the bat / a dumbbell) and, for",
    "-- crates, the lid hinge. Axes as exported: X, Y up, Z = Blender -Y (the item's front is +Z here; the 3D",
    "-- Importer has turned past meshes 180 degrees about Y, so check the turn in Studio: Config.ItemModels).",
    "",
    "export type Entry = { size: Vector3, center: Vector3, hinge: Vector3? }",
    "",
    "return {",
]
for name in sorted(man):
    e = man[name]
    extra = f", hinge = {v3(e['hinge'])}" if "hinge" in e else ""
    lines.append(f"\t{name} = {{ size = {v3(e['size'])}, center = {v3(e['center'])}{extra} }},")
lines.append("} :: { [string]: Entry }")
with open(os.path.join(root, "src", "shared", "ItemModelData.luau"), "w", newline="\n") as f:
    f.write("\n".join(lines) + "\n")
print(len(man), "meshes")
